#include <string>
#include <sstream>
#include <unordered_map>

class Solution {
public:
    std::string reformatDate(std::string date) {
        std::unordered_map<std::string, std::string> months = {
            {"Jan", "01"}, {"Feb", "02"}, {"Mar", "03"}, {"Apr", "04"},
            {"May", "05"}, {"Jun", "06"}, {"Jul", "07"}, {"Aug", "08"},
            {"Sep", "09"}, {"Oct", "10"}, {"Nov", "11"}, {"Dec", "12"}
        };
        std::stringstream ss(date);
        std::string d, m, y;
        ss >> d >> m >> y;
        std::string dayNum = "";
        for (char c : d) if (std::isdigit(c)) dayNum += c;
        if (dayNum.size() == 1) dayNum = "0" + dayNum;
        return y + "-" + months[m] + "-" + dayNum;
    }
};

import java.util.*;

class Solution {
    public String reformatDate(String date) {
        Map<String, String> months = new HashMap<>();
        String[] names = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};
        for (int i = 0; i < 12; i++) {
            months.put(names[i], String.format("%02d", i + 1));
        }
        String[] parts = date.split(" ");
        String dayStr = parts[0].replaceAll("[^0-9]", "");
        if (dayStr.length() == 1) dayStr = "0" + dayStr;
        return parts[2] + "-" + months.get(parts[1]) + "-" + dayStr;
    }
}

var reformatDate = function(date) {
    const months = {
        "Jan": "01", "Feb": "02", "Mar": "03", "Apr": "04",
        "May": "05", "Jun": "06", "Jul": "07", "Aug": "08",
        "Sep": "09", "Oct": "10", "Nov": "11", "Dec": "12"
    };
    const [d, m, y] = date.split(" ");
    const dayNum = d.replace(/\D/g, "").padStart(2, "0");
    return `${y}-${months[m]}-${dayNum}`;
};
